import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Attributes.md","filePath":"manual-en/Attributes.md","lastUpdated":1785684581000}'),r={name:"manual-en/Attributes.md"};function n(o,e,l,d,p,c){return t(),i("div",null,[...e[0]||(e[0]=[s('<h4 id="_6-7-1-attributes-of-variables" tabindex="-1">6.7.1 Attributes of Variables <a class="header-anchor" href="#_6-7-1-attributes-of-variables" aria-label="Permalink to &quot;6.7.1 Attributes of Variables&quot;">​</a></h4><p>Each variable has a number of attributes, including:</p><p><strong>Name</strong></p><p>An identifier, up to 64 bytes long. Each variable must have a different name. See <a href="./Tokens">Tokens</a>.</p><p>Some system variable names begin with ‘$’, but user-defined variables’ names may not begin with ‘$’.</p><p>The final character in a variable name should not be ‘.’, because such an identifier will be misinterpreted when it is the final token on a line: <code>FOO.</code> is divided into two separate tokens, ‘FOO’ and ‘.’, indicating end-of-command. See <a href="./Tokens">Tokens</a>.</p><p>The final character in a variable name should not be ‘_’, because some such identifiers are used for special purposes by PSPP procedures.</p><p>As with all PSPP identifiers, variable names are not case-sensitive. PSPP capitalizes variable names on output the same way they were capitalized at their point of definition in the input.</p><p><strong>Type</strong></p><p>Numeric or string.</p><p><strong>Width</strong></p><p>(string variables only) String variables with a width of 8 characters or fewer are called <em>short string variables</em>. Short string variables may be used in a few contexts where <em>long string variables</em> (those with widths greater than 8) are not allowed.</p><p><strong>Position</strong></p><p>Variables in the dictionary are arranged in a specific order. <code>DISPLAY</code> can be used to show this order: see <a href="./DISPLAY">DISPLAY</a>.</p><p><strong>Initialization</strong></p><p>Either reinitialized to 0 or spaces for each case, or left at its existing value. See <a href="./LEAVE">LEAVE</a>.</p><p><strong>Missing values</strong></p><p>Optionally, up to three values, or a range of values, or a specific value plus a range, can be specified as <em>user-missing values</em>. There is also a <em>system-missing value</em> that is assigned to an observation when there is no other obvious value for that observation. Observations with missing values are automatically excluded from analyses. User-missing values are actual data values, while the system-missing value is not a value at all. See <a href="./Missing-Observations">Missing Observations</a>.</p><p><strong>Variable label</strong></p><p>A string that describes the variable. See <a href="./VARIABLE-LABELS">VARIABLE LABELS</a>.</p><p><strong>Value label</strong></p><p>Optionally, these associate each possible value of the variable with a string. See <a href="./VALUE-LABELS">VALUE LABELS</a>.</p><p><strong>Print format</strong></p><p>Display width, format, and (for numeric variables) number of decimal places. This attribute does not affect how data are stored, just how they are displayed. Example: a width of 8, with 2 decimal places. See <a href="./Input-and-Output-Formats">Input and Output Formats</a>.</p><p><strong>Write format</strong></p><p>Similar to print format, but used by the <code>WRITE</code> command (see <a href="./WRITE">WRITE</a>).</p><p><strong>Measurement level</strong></p><p>One of the following:</p><p>Nominal</p><p>Each value of a nominal variable represents a distinct category. The possible categories are finite and often have value labels. The order of categories is not significant. Political parties, US states, and yes/no choices are nominal. Numeric and string variables can be nominal.</p><p>Ordinal</p><p>Ordinal variables also represent distinct categories, but their values are arranged according to some natural order. Likert scales, e.g. from strongly disagree to strongly agree, are ordinal. Data grouped into ranges, e.g. age groups or income groups, are ordinal. Both numeric and string variables can be ordinal. String values are ordered alphabetically, so letter grades from A to F will work as expected, but <code>poor</code>, <code>satisfactory</code>, <code>excellent</code> will not.</p><p>Scale</p><p>Scale variables are ones for which differences and ratios are meaningful. These are often values which have a natural unit attached, such as age in years, income in dollars, or distance in miles. Only numeric variables are scalar.</p><p>Variables created by <code>COMPUTE</code> and similar transformations, obtained from external sources, etc., initially have an unknown measurement level. Any procedure that reads the data will then assign a default measurement level. PSPP can assign some defaults without reading the data:</p><ul><li>Nominal, if it’s a string variable.</li><li>Nominal, if the variable has a WKDAY or MONTH print format.</li><li>Scale, if the variable has a DOLLAR, CCA through CCE, or time or date print format.</li></ul><p>Otherwise, PSPP reads the data and decides based on its distribution:</p><ul><li>Nominal, if all observations are missing.</li><li>Scale, if one or more valid observations are noninteger or negative.</li><li>Scale, if no valid observation is less than 10.</li><li>Scale, if the variable has 24 or more unique valid values. The value 24 is the default and can be adjusted (see <a href="./SET#SET-SCALEMIN">SET SCALEMIN</a>).</li></ul><p>Finally, if none of the above is true, PSPP assigns the variable a nominal measurement level.</p><p><strong>Custom attributes</strong></p><p>User-defined associations between names and values. See <a href="./VARIABLE-ATTRIBUTE">VARIABLE ATTRIBUTE</a>.</p><p><strong>Role</strong></p><p>The intended role of a variable for use in dialog boxes in graphical user interfaces. See <a href="./VARIABLE-ROLE">VARIABLE ROLE</a>.</p>',43)])])}const m=a(r,[["render",n]]);export{u as __pageData,m as default};
